import { z } from "zod";
import { basic, createAction, createApp } from "@cloudfarm/computer";

/**
 * Jira as an app plugin.
 *
 * Jira Cloud is per-site, so `site` is a constructor option rather than an
 * argument: it decides the base URL and therefore the egress allowlist, and
 * a value that decides where a credentialed request may go must not arrive
 * from a model.
 *
 * Descriptions and comments are Atlassian Document Format, not markdown.
 * The spec wraps plain text in the smallest valid document, which is what
 * an agent wants in the overwhelming majority of cases.
 */
export const jira = createApp({
  id: "jira",
  name: "Jira",
  description:
    "Issue tracking. Search issues with JQL, read one, create issues, comment on them, and list projects.",
  icon: "https://cdn.simpleicons.org/jira",
  auth: basic(),
  options: z.object({
    site: z.string().describe('Atlassian site name — the "acme" in acme.atlassian.net.'),
    baseUrl: z
      .string()
      .url()
      .optional()
      .describe("Override the API base, for a proxy or a test double."),
  }),
  allowedHosts: ({ site }) => [`${site}.atlassian.net`],
  http: ({ baseUrl, site }) => ({
    baseUrl: baseUrl ?? `https://${site}.atlassian.net/rest/api/3`,
  }),

  actions: {
    searchIssues: createAction({
      summary: "Search issues with JQL.",
      useCases: [
        "search jira",
        "find a jira ticket",
        "what issues are assigned to me in jira",
        "list open bugs in jira",
        "what is in this sprint",
      ],
      keywords: ["jql", "ticket", "sprint"],
      sideEffects: "read",
      input: z.object({
        jql: z
          .string()
          .min(1)
          .describe('JQL, e.g. "project = ENG AND statusCategory != Done ORDER BY updated DESC".'),
        limit: z.number().int().min(1).max(100).optional(),
      }),
      output: z.object({
        issues: z.array(
          z.object({
            key: z.string().describe('Human reference, e.g. "ENG-42".'),
            summary: z.string(),
            status: z.string(),
            assignee: z.string().optional(),
            updated: z.string().optional(),
          }),
        ),
      }),
      example: '{ jql: "project = ENG ORDER BY updated DESC" }',
      handler: async ({ jql, limit = 25 }, context) => {
        const body = await context.http.get("search/jql", {
          query: { jql, maxResults: limit, fields: "summary,status,assignee,updated" },
        });
        const mappedIssues = [];
        for (const item of list(at(body, "issues"))) {
          const rawAssignee = at(item, "fields.assignee.displayName");
          const rawUpdated = at(item, "fields.updated");
          mappedIssues.push({
            key: str(at(item, "key")),
            summary: str(at(item, "fields.summary")),
            status: str(at(item, "fields.status.name")),
            ...(rawAssignee === undefined || rawAssignee === null
              ? {}
              : { assignee: str(rawAssignee) }),
            ...(rawUpdated === undefined || rawUpdated === null
              ? {}
              : { updated: str(rawUpdated) }),
          });
        }
        return { issues: mappedIssues };
      },
    }),

    getIssue: createAction({
      summary: "Read one issue by key.",
      useCases: ["read a jira issue", "what is ENG-42", "look up a ticket by key"],
      sideEffects: "read",
      input: z.object({
        key: z.string().describe('Issue key, e.g. "ENG-42".'),
      }),
      output: z.object({
        key: z.string(),
        summary: z.string(),
        status: z.string(),
        assignee: z.string().optional(),
        created: z.string().optional(),
        description: z.unknown().describe("Atlassian Document Format.").optional(),
      }),
      example: '{ key: "ENG-42" }',
      handler: async ({ key }, context) => {
        const body = await context.http.get(`issue/${encodeURIComponent(String(key))}`, {
          query: { fields: "summary,status,assignee,description,created" },
        });
        const rawAssignee = at(body, "fields.assignee.displayName");
        const rawCreated = at(body, "fields.created");
        const rawDescription = at(body, "fields.description");
        return {
          key: str(at(body, "key")),
          summary: str(at(body, "fields.summary")),
          status: str(at(body, "fields.status.name")),
          ...(rawAssignee === undefined || rawAssignee === null
            ? {}
            : { assignee: str(rawAssignee) }),
          ...(rawCreated === undefined || rawCreated === null ? {} : { created: str(rawCreated) }),
          ...(rawDescription === undefined || rawDescription === null
            ? {}
            : { description: rawDescription }),
        };
      },
    }),

    createIssue: createAction({
      summary: "Create an issue in a project.",
      useCases: ["create a jira issue", "file a jira ticket", "open a task in jira", "log a bug"],
      sideEffects: "write",
      input: z.object({
        projectKey: z.string().describe('Project key, e.g. "ENG".'),
        summary: z.string().min(1).describe("One-line title."),
        issueType: z.string().optional(),
      }),
      output: z.object({
        id: z.string(),
        key: z.string(),
        url: z.string(),
      }),
      example: '{ projectKey: "ENG", summary: "Login fails on Safari" }',
      handler: async ({ projectKey, summary, issueType = "Task" }, context) => {
        const body = await context.http.post("issue", {
          fields: { project: { key: projectKey }, summary, issuetype: { name: issueType } },
        });
        return { id: str(at(body, "id")), key: str(at(body, "key")), url: str(at(body, "self")) };
      },
    }),

    addComment: createAction({
      summary: "Comment on an issue.",
      useCases: ["comment on a jira issue", "reply on a jira ticket", "add a note to ENG-42"],
      sideEffects: "write",
      input: z.object({
        key: z.string().describe('Issue key, e.g. "ENG-42".'),
        text: z.string().min(1).describe("Plain text; wrapped in ADF for you."),
      }),
      output: z.object({
        id: z.string(),
        created: z.string(),
        author: z.string().optional(),
      }),
      example: '{ key: "ENG-42", text: "Reproduced on 17.4." }',
      handler: async ({ key, text }, context) => {
        const body = await context.http.post(`issue/${encodeURIComponent(String(key))}/comment`, {
          body: {
            type: "doc",
            version: 1,
            content: [{ type: "paragraph", content: [{ type: "text", text }] }],
          },
        });
        const rawAuthor = at(body, "author.displayName");
        return {
          id: str(at(body, "id")),
          created: str(at(body, "created")),
          ...(rawAuthor === undefined || rawAuthor === null ? {} : { author: str(rawAuthor) }),
        };
      },
    }),

    listProjects: createAction({
      summary: "List projects, with the keys other actions need.",
      useCases: ["list jira projects", "what projects exist in jira", "find a project key"],
      sideEffects: "read",
      input: z.object({
        limit: z.number().int().min(1).max(100).optional(),
      }),
      output: z.object({
        projects: z.array(
          z.object({
            id: z.string(),
            key: z.string(),
            name: z.string(),
          }),
        ),
      }),
      example: "{}",
      handler: async ({ limit = 50 }, context) => {
        const body = await context.http.get("project/search", { query: { maxResults: limit } });
        return {
          projects: list(at(body, "values")).map((item) => ({
            id: str(at(item, "id")),
            key: str(at(item, "key")),
            name: str(at(item, "name")),
          })),
        };
      },
    }),
  },
});

/** What `jira(…)` takes: the auth scheme's input plus the options schema. */
export type JiraOptions = Parameters<typeof jira>[0];

